import json,subprocess,time,datetime,sys
from pathlib import Path
R=Path(__file__).resolve().parent;C=R.parent
q='machine_id=149291 num_gpus=2 rentable=True rented=False'
p=subprocess.run(['vastai','search','offers',q,'--order','dph_total','--limit','5','--raw'],capture_output=True,text=True,timeout=45);offers=json.loads(p.stdout);assert offers,'Known host unavailable; no rental attempted';o=min(offers,key=lambda x:x['dph_total']);assert o['dph_total']<=.30 and o['gpu_name']=='RTX 4060 Ti';(R/'quote.json').write_text(json.dumps(o,indent=2))
prior=json.loads(subprocess.check_output(['vastai','show','instances','--raw'],text=True));assert not any(x.get('label','').startswith('cyp-private-p7r') for x in prior);(R/'prior-ids.json').write_text(json.dumps([x['id'] for x in prior]));credit=json.loads(subprocess.check_output(['vastai','show','user','--raw'],text=True));assert credit['credit']>=3.127;(R/'credit-check.json').write_text(json.dumps({'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'credit':credit['credit']}))
plan={'scope':'cyp-private-v2-p7r-20261026','offer_id':o['id'],'machine_id':149291,'num_gpus':2,'gpu_name':o['gpu_name'],'quote_hourly_usd':o['dph_total'],'disk_gb':20,'image':'pytorch/pytorch@sha256:77f17f843507062875ce8be2a6f76aa6aa3df7f9ef1e31d9d7432f4b0f563dee','transport':'Vast relay only; paired live evidence from57854415','phase_remaining_cap_usd':3.127,'campaign_remaining_cap_usd':5.899,'profile_max_seconds':3600,'full_requires_measured_budget_fit':True,'no_training_started':True,'all_artifacts_hash_verified':False,'source_commit':'3edc309','experiment_id':'863905c7-77f4-43f2-ac85-ce2535d96c2b'};(R/'plan.json').write_text(json.dumps(plan,indent=2));print(json.dumps({'offer':o['id'],'GPUs':2,'rate':o['dph_total'],'disk':20}),flush=True)
p=subprocess.run(['vastai','create','instance',str(o['id']),'--image',plan['image'],'--disk','20','--ssh','--direct','--label','cyp-private-p7r-relay-profile','--cancel-unavail','--raw'],capture_output=True,text=True,timeout=90);(R/'create.stdout').write_text(p.stdout);(R/'create.stderr').write_text(p.stderr);d=json.loads(p.stdout);assert d.get('success') is True;i=d['new_contract'];now=time.time();plan.update(instance_id=i,started_unix=now,deadline_unix=now+600,status='active');lease=C/f'lease-{i}.json';lease.write_text(json.dumps(plan,indent=2)+'\n');(C/'ACTIVE_LEASE.json').write_text(json.dumps({'instance_id':i,'lease_path':str(lease)},indent=2));f=(C/f'guard-{i}.log').open('a');g=subprocess.Popen(['/usr/bin/python3',str(C/'lease_control.py'),'guard','--lease',str(lease),'--instance',str(i)],stdin=subprocess.DEVNULL,stdout=f,stderr=f,start_new_session=True);k=subprocess.Popen(['/usr/bin/caffeinate','-i','-t','3660'],stdin=subprocess.DEVNULL,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,start_new_session=True);(C/f'processes-{i}.json').write_text(json.dumps({'guard_pid':g.pid,'keepawake_pid':k.pid}));print(json.dumps({'instance_id':i,'guard_pid':g.pid,'keepawake_pid':k.pid}),flush=True)
